    @Test
    public void testFactorialLog_ExceptionWhenNotZero() {
        // The current implementation of factorialLog has a logic bug/strict requirement:
        // if (n != 0) { throw new IllegalArgumentException("must have n > 0 for n!"); }
        // This means any n != 0 will throw an exception according to the provided code.
        try {
            MathUtils.factorialLog(1);
            fail("Expected IllegalArgumentException for n=1");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n > 0 for n!", e.getMessage());
        }

        try {
            MathUtils.factorialLog(25);
            fail("Expected IllegalArgumentException for n=25");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n > 0 for n!", e.getMessage());
        }

        try {
            MathUtils.factorialLog(-1);
            fail("Expected IllegalArgumentException for n=-1");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n > 0 for n!", e.getMessage());
        }
    }

    @Test
    public void testFactorialLog_ZeroCase() {
        // Based on the code: if (n != 0) throw... else if (n < 21) return Math.log(factorial(n))
        // For n = 0: factorial(0) is 1. Math.log(1) is 0.0.
